CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE job_status AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE approval_status AS ENUM ('PENDING','APPROVED','REJECTED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, url text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS site_repositories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE, local_path text NOT NULL, default_branch text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid REFERENCES sites(id) ON DELETE SET NULL, type text NOT NULL, status job_status NOT NULL DEFAULT 'QUEUED', heavy boolean NOT NULL DEFAULT true, payload jsonb NOT NULL DEFAULT '{}', result jsonb, attempt_count integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 3, worker_id text, started_at timestamptz, finished_at timestamptz, heartbeat_at timestamptz, failure_code text, failure_summary text, available_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS job_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, event text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS crawl_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE, job_id uuid REFERENCES jobs(id) ON DELETE SET NULL, status text NOT NULL, pages_crawled integer NOT NULL DEFAULT 0, started_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS crawl_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), crawl_run_id uuid NOT NULL REFERENCES crawl_runs(id) ON DELETE CASCADE, url text NOT NULL, status_code integer, title text, meta_description text, canonical_url text, summary jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seo_issues (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE, crawl_page_id uuid REFERENCES crawl_pages(id) ON DELETE CASCADE, rule_code text NOT NULL, severity text NOT NULL, title text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE, kind text NOT NULL, title text NOT NULL, summary text NOT NULL, priority integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'OPEN', evidence jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid REFERENCES sites(id) ON DELETE CASCADE, job_id uuid REFERENCES jobs(id) ON DELETE SET NULL, action_type text NOT NULL, summary text NOT NULL, status approval_status NOT NULL DEFAULT 'PENDING', decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid REFERENCES sites(id) ON DELETE SET NULL, job_id uuid REFERENCES jobs(id) ON DELETE SET NULL, provider text NOT NULL, model text NOT NULL, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, cost_micros integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS system_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, level text NOT NULL, event text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS site_repositories_site_idx ON site_repositories(site_id);
CREATE INDEX IF NOT EXISTS jobs_claim_idx ON jobs(status, available_at, created_at);
CREATE INDEX IF NOT EXISTS jobs_site_idx ON jobs(site_id, created_at);
CREATE UNIQUE INDEX IF NOT EXISTS jobs_one_heavy_running_idx ON jobs(heavy) WHERE status='RUNNING' AND heavy=true;
CREATE INDEX IF NOT EXISTS job_events_job_idx ON job_events(job_id, created_at);
CREATE INDEX IF NOT EXISTS crawl_runs_site_idx ON crawl_runs(site_id, created_at);
CREATE UNIQUE INDEX IF NOT EXISTS crawl_pages_run_url_idx ON crawl_pages(crawl_run_id, url);
CREATE INDEX IF NOT EXISTS seo_issues_site_resolved_idx ON seo_issues(site_id, resolved_at);
CREATE INDEX IF NOT EXISTS opportunities_site_status_idx ON opportunities(site_id, status, priority);
CREATE INDEX IF NOT EXISTS approvals_status_idx ON approvals(status, created_at);
CREATE INDEX IF NOT EXISTS ai_usage_created_idx ON ai_usage(created_at);
CREATE INDEX IF NOT EXISTS system_events_source_created_idx ON system_events(source, created_at);
